function f2Head(title,subtitle,back){return '<header class="sh__h f2-head">'+(back?'<button class="m3-icon-button" data-act="card" data-v="'+esc(back)+'" aria-label="Về thẻ">'+mi('arrow_back')+'</button>':'')+'<div><b id="f2DialogTitle">'+esc(title)+'</b>'+(subtitle?'<small>'+esc(subtitle)+'</small>':'')+'</div><button class="m3-icon-button" data-act="close" aria-label="Đóng">'+mi('close')+'</button></header>';}
function f2Mount(kind,html,keepScroll){if(!OV)return;var s=$('.sheet',OV),top=s.scrollTop,oldBody=$('.f2-body',s),bodyTop=oldBody?oldBody.scrollTop:0,same=s.classList.contains('f2-'+kind);sheetSet(html);s.className='sheet f2-sheet f2-'+kind+(kind==='detail'?' habit-sheet33':kind==='checkin'?' checkin-sheet':kind==='how'?' howpg':'');OV.classList.add('f2-overlay');OV.setAttribute('aria-labelledby','f2DialogTitle');if(keepScroll&&same){s.scrollTop=top;var body=$('.f2-body',s);if(body)body.scrollTop=bodyTop;}}
function f2Identity(id){var x=HMAP[id];return '<div class="f2-identity"><span class="m3-row-icon">'+mi(m3HabitIcon(id))+'</span><div><h2>'+esc(hname(id))+'</h2><p>'+esc((H(id)||{}).act||x.act||'')+'</p></div></div>';}
recordOptions29=function(id,value,act){var choices=isDip(id)?['y','n','x']:['y','p','n'];return '<div class="record-options f2-options" role="group" aria-label="Kết quả của '+esc(sname(id))+'">'+choices.map(function(m){return '<button class="record-option state-'+m+'" data-act="'+act+'" data-v="'+id+'|'+m+'" aria-pressed="'+(value===m)+'">'+(m==='y'?mi('check_circle'):m==='n'?mi('close'):m==='x'?mi('style'):'<span class="f2-partial" aria-hidden="true">−</span>')+'<span>'+esc(RECORD_LABEL[m])+'</span></button>';}).join('')+'</div>';};
function f2Hints(id,status,act,valuePrefix,open){var E=noteHints34(id,status);return '<details class="f2-suggestions"'+(valuePrefix?' data-ci-detail="hint-'+id+'"':'')+(open?' open':'')+'><summary>Gợi ý ghi chú'+mi('expand_more')+'</summary><div>'+E.o.map(function(o){return '<button class="chp" data-act="'+act+'" data-v="'+esc((valuePrefix?id+'|':'')+o)+'">'+esc(o)+'</button>';}).join('')+'</div></details>';}
drawNote29=function(){if(!NT)return;var id=NT.id,E=noteHints34(id,NT.ans),has=!!mark(NT.day,id);f2Mount('record',f2Head('Ghi nhận thói quen',NT.day===dk()?'Hôm nay':('Ghi bù · '+treeDate30(NT.day)))+'<div class="f2-body">'+f2Identity(id)+recordOptions29(id,NT.ans,'recordAnswer')+(NT.ans==='n'?'<details class="f2-reasons"><summary>Lý do'+mi('expand_more')+'</summary><div>'+REASONS.map(function(r){return '<button class="chp'+(NT.why===r[0]?' on':'')+'" data-act="recordWhy" data-v="'+r[0]+'" aria-pressed="'+(NT.why===r[0])+'">'+esc(r[1])+'</button>';}).join('')+'</div></details>':'')+'<div class="f2-note-field"><label class="lbl" for="ntIn">'+esc(E.q)+' <small>· Bắt buộc</small></label><textarea class="inp" id="ntIn" data-in="note" rows="3" required aria-required="true" aria-describedby="ntRequired34" placeholder="Ghi lại một điều cụ thể">'+esc(NT.text)+'</textarea><p class="f2-error" id="ntRequired34" role="alert" hidden>Viết một ghi chú ngắn trước khi lưu nhé.</p></div>'+f2Hints(id,NT.ans,'ntChip',false,false)+'</div><footer class="sbar f2-footer f2-record-footer">'+(has?'<button class="f2-text-button f2-remove" data-act="recordRemove">Bỏ ghi nhận</button>':'<span></span>')+'<button class="btn" id="ntGo" data-act="ntSave"'+(String(NT.text||'').trim()?'':' disabled')+'>'+mi('check')+'Lưu ghi nhận</button></footer>',true);};
ciNoteInputs34=function(id,status){var E=noteHints34(id,status);return '<div class="ci34-note f2-note-field"><label class="lbl" for="ci-note-'+id+'">'+esc(E.q)+' <small>· Bắt buộc</small></label><textarea class="inp" id="ci-note-'+id+'" data-in="ciNote29" data-id="'+id+'" required aria-required="true" rows="2" placeholder="Ghi lại một điều cụ thể">'+esc(CI.notes[id]||'')+'</textarea>'+f2Hints(id,status,'ciNoteChip34',true,!!CI.open['hint-'+id])+'</div>';};
ciRow29=function(id){var a=CI.ans[id]||'',skip=!!CI.skip[id];return '<article class="ci29-row f2-ci-row" data-ci-row="'+id+'"><div class="f2-ci-row-head"><span class="m3-row-icon">'+mi(m3HabitIcon(id))+'</span><div><h3>'+esc(sname(id))+'</h3><p>'+esc(H(id).act)+'</p></div><button class="f2-text-button'+(skip?' selected':'')+'" data-act="'+(CI.base[id]?'ciKeepExisting29':'ciSkip29')+'" data-v="'+id+'" aria-pressed="'+skip+'">'+(CI.base[id]?'Giữ như cũ':skip?'Đã để sau':'Để sau')+'</button></div>'+recordOptions29(id,a,'ciAnswer29')+(a?ciNoteInputs34(id,a):'')+'</article>';};
ciKeeps34=function(){return '<section class="f2-ci-keeps"><div class="f2-section-heading"><h3>Giữ nếp nhẹ nhàng</h3><p>Hôm nay bạn duy trì được thói quen nào?</p></div><div class="f2-keep-chips">'+CI.keeps.map(function(id){return '<button class="chp'+(CI.keep[id]?' on':'')+'" data-act="ciKeep29" data-v="'+id+'" aria-pressed="'+!!CI.keep[id]+'">'+(CI.keep[id]?mi('check'):'')+esc(sname(id))+'</button>';}).join('')+'</div>'+CI.keeps.filter(function(id){return CI.keep[id];}).map(function(id){return '<div class="f2-ci-keep-note"><b>'+esc(sname(id))+'</b>'+ciNoteInputs34(id,'y')+'</div>';}).join('')+'</section>';};
function f2CISaveError(){return '<div class="f2-save-error" role="alert"><span>'+mi('info')+'</span><h2>Chưa lưu trên máy.</h2><p>Phần đang làm vẫn còn trong trang này. Bạn thử lưu lại, hoặc xuất bản sao trước khi đóng nhé.</p></div>';}
drawCI=function(){if(!CI)return;if(CI.done){var failed=SAVE_STATE32==='error';f2Mount('checkin',f2Head(failed?'Check-in chưa lưu':'Check-in đã lưu',treeDate30(CI.date))+'<div class="f2-body f2-ci-complete">'+(failed?f2CISaveError():ciSummary())+'</div><footer class="sbar f2-footer'+(failed?' f2-failure-footer':'')+'">'+(failed?m3Button('backup',null,'Xuất bản sao','download','tonal')+m3Button('retrySave32',null,'Thử lưu lại','save'):'<button class="btn btn--wide" data-act="ciHome29">Về Hôm nay'+mi('arrow_forward')+'</button>')+'</footer>');return;}var s=ciState(),pending=CI.all.filter(function(id){return !CI.base[id]||CI.edit[id]||!String(CI.notes[id]||'').trim();}),recorded=CI.all.filter(function(id){return CI.base[id]&&!CI.edit[id]&&String(CI.notes[id]||'').trim();});var h=f2Head(CI.date===dk()?'Check-in tối nay':'Check-in',treeDate30(CI.date))+'<div class="f2-body"><div class="f2-ci-intro"><span class="f2-moon">'+mi('nightlight')+'</span><h2>'+(CI.date===dk()?'Rà lại hôm nay, nhẹ thôi.':'Nhìn lại ngày '+dm(CI.date)+'.')+'</h2><p>'+(CI.again?'Bạn có thể chỉnh lại kết quả đã lưu.':'Những thẻ đã ghi được giữ nguyên. Chỉ cần chọn cho các thẻ còn lại.')+'</p></div>';
  if(recorded.length)h+='<details class="ci29-recorded f2-recorded" data-ci-detail="saved"'+(CI.open.saved?' open':'')+'><summary>'+mi('check_circle')+'<span>'+recorded.length+' thẻ đã ghi nhận</span><small>Xem / chỉnh</small>'+mi('expand_more')+'</summary><div>'+recorded.map(function(id){return '<div class="f2-recorded-row"><b>'+esc(sname(id))+'</b><span class="m3-status '+CI.ans[id]+'">'+esc(RECORD_LABEL[CI.ans[id]])+'</span><button class="f2-text-button" data-act="ciEdit29" data-v="'+id+'" aria-label="Chỉnh '+esc(sname(id))+'">Chỉnh</button></div>';}).join('')+'</div></details>';
  if(pending.length)h+='<h3 class="f2-section-label">'+(recorded.length?'Các thẻ còn lại':'Thói quen hôm nay')+'</h3><div class="f2-ci-list">'+pending.map(ciRow29).join('')+'</div>';
  if(CI.keeps.length)h+=ciKeeps34();
  h+='<section class="f2-ci-mood"><div class="f2-section-heading"><h3>'+(CI.date===dk()?'Hôm nay':'Hôm đó')+' bạn thấy thế nào?</h3><p>Không bắt buộc · Chỉ bạn xem</p></div><div class="ci29-mood-options">'+(window.innerWidth<768?MOODS.slice().reverse():MOODS).map(function(m){return '<button data-act="ciMood29" data-v="'+m[0]+'" aria-pressed="'+(CI.mood===m[0])+'">'+moodFace(+m[0],m[2])+'<span>'+esc(m[1])+'</span></button>';}).join('')+'</div></section><details class="ci29-memo f2-ci-memo" data-ci-detail="memo"'+(CI.open.memo?' open':'')+'><summary><span>Viết một câu cho hôm nay<small>Không bắt buộc</small></span>'+mi('expand_more')+'</summary><label class="lbl" for="ciMemo29">'+esc(PROMPTS[CI.pi])+'</label><textarea class="inp" id="ciMemo29" data-in="ciMemo29" rows="3" placeholder="'+esc(PROMPT_PH[CI.pi])+'">'+esc(CI.note)+'</textarea></details></div><footer class="sbar ci29-footer f2-footer f2-ci-footer"><div><b aria-live="polite">'+s.msg+'</b>'+(s.remaining?'<button class="f2-text-button" data-act="ciRest29">Để các thẻ còn lại sang sau</button>':'<small>Memo cuối ngày và cảm xúc tùy chọn.</small>')+'</div><button class="btn" data-act="ciSave29"'+(s.ok?'':' disabled')+'>'+mi('check')+(CI.again?'Lưu thay đổi':'Lưu check-in')+'</button></footer>';f2Mount('checkin',h);
};
ciSummary=function(){var ids=CI.all.concat(CI.keeps.filter(function(id){return !!mark(CI.date,id);})),counts={y:0,p:0,n:0,x:0,unlogged:0};ids.forEach(function(id){counts[mark(CI.date,id)||'unlogged']++;});return '<div class="f2-ci-success"><div class="f2-success-shin">'+shin('proud')+'</div><span class="f2-success-label">'+mi('check_circle')+'Đã lưu</span><h2>'+esc(CI.date===dk()?'Đã lưu hôm nay.':'Đã lưu ngày '+dm(CI.date)+'.')+'</h2><p>Một lần nhìn lại, một bước hiểu mình hơn.</p><div class="f2-success-counts">'+[['y','Đã làm'],['p','Một phần'],['unlogged','Để sau']].map(function(c){return '<div><b>'+counts[c[0]]+'</b><span>'+c[1]+'</span></div>';}).join('')+'</div>'+(counts.n||counts.x?'<p class="f2-success-other">'+(counts.n?counts.n+' chưa làm':'')+(counts.n&&counts.x?' · ':'')+(counts.x?counts.x+' không gặp dịp':'')+'</p>':'')+'<p class="f2-success-message">'+(counts.unlogged?'Các thẻ để sau vẫn chưa có dấu. Bạn có thể ghi nhận khi sẵn sàng.':counts.n?'Ngày nào cũng có lúc chưa trọn vẹn. Mai mình thử một việc nhỏ vừa sức.':'Bạn có thể xem lại các ghi nhận trong tab Tuần.')+'</p></div>';};
habitHeader33=function(id,tab){return f2Head(sname(id),'',null)+'<div class="habit-tabs33 f2-detail-tabs" role="tablist" aria-label="Nội dung thói quen">'+[['card','style','Thẻ thói quen'],['journal','auto_stories','Nhật ký']].map(function(t){return '<button id="habit-tab-'+t[0]+'" role="tab" aria-controls="habit-body33" aria-selected="'+(tab===t[0])+'" tabindex="'+(tab===t[0]?'0':'-1')+'" data-act="habitTab33" data-v="'+t[0]+'">'+mi(t[1])+t[2]+'</button>';}).join('')+'</div>';};
function f2Days(id){var t=dk(),ws=wkStart(t),u=H(id);return '<div class="f2-card-week"><span>Tuần này</span><div>'+WDS.map(function(w,i){var d=addD(ws,i),m=mark(d,id),future=d>t||(u&&d<u.since),edit=u&&!m&&u.status!=='keep'&&canBf(d,id),tag=edit?'button':'span';return '<'+tag+' class="f2-day '+(m||'unlogged')+(future?' future':'')+(d===t?' today':'')+'"'+(edit?' data-act="note" data-v="'+id+'|'+d+'"':'')+' aria-label="'+w+', '+treeDate30(d)+': '+(RECORD_LABEL[m]||(edit?'Ghi bù':future?'Chưa tới ngày':'Chưa ghi'))+'"><small>'+w+'</small><i>'+(m==='y'?mi('check'):m==='p'?'−':m==='n'?'×':m==='x'?'·':'')+'</i></'+tag+'>';}).join('')+'</div></div>';}
function f2DetailFront(id){var x=HMAP[id],u=H(id),lv=u?u.lv:0,n=u?daysAt(id):0,need=u?needFor(id,lv):0;return '<article class="f2-detail-paper"><div class="f2-paper-top"><span class="m3-emblem">'+mi(m3HabitIcon(id))+'</span><span class="m3-eyebrow">'+(lv?'CẤP '+lv+' · '+esc(LV_NAME[lv]):x.custom?'THẺ TỰ TẠO':'KAIZEN · '+cardNo(id))+'</span>'+(u&&S.slots.indexOf(id)>=0?'<button class="m3-icon-button" data-act="edit" data-v="'+id+'" aria-label="Sửa thẻ">'+mi('edit')+'</button>':'')+'</div><h2>'+esc(hname(id))+'</h2><div class="f2-formula"><small>'+(u?'KHI':'BẮT ĐẦU')+'</small><p>'+esc(u?u.anchor:x.tiers[0])+'</p><small>'+(u?'MÌNH SẼ':'TRỞ THÀNH')+'</small><p class="f2-formula-action">'+esc(u?u.act:x.who[0])+'</p></div>'+f2Days(id)+(u?'<div class="f2-owner"><div><b>'+esc(S.name)+'</b><small>Rèn từ '+dm(u.since)+'</small></div><span>'+Math.min(n,need)+' / '+need+' '+unitOf(id)+'</span></div><div class="m3-progress-track"><i style="width:'+Math.round(lvPct(id)*100)+'%"></i></div>':'<p class="f2-unowned">Thẻ chưa có chủ</p>')+'</article>';}
function f2DetailBack(id){var x=HMAP[id],u=H(id),pv=x.prov||x.jp,v=spOf(id);return '<article class="f2-detail-meaning"><div class="f2-meaning-art">'+metaSVG(id)+'</div><p class="m3-kicker">'+(x.custom?'VÌ SAO MÌNH CHỌN':'Ý NGHĨA · 意味')+'</p>'+(x.custom?'<blockquote><small>LỜI CỦA '+esc(String(S.name||'').toUpperCase())+'</small><p>'+esc(x.myWhy||'')+'</p></blockquote>':'<div class="f2-japanese"><div><p lang="ja">'+esc(pv.j)+'</p><small>'+esc(pv.r)+'</small><p>'+esc(pv.v)+'</p></div><button class="m3-icon-button" data-act="speak" data-v="'+esc(pv.j)+'" aria-label="Nghe đọc">'+mi('volume_up')+'</button></div><p class="f2-meaning-benefit">'+esc(BEN[id]||(x.why?x.why.now:'Để trở thành '+x.who[0]+'.'))+'</p>'+((x.corner||x.kase)?'<button class="f2-senpai" data-act="senpai" data-v="'+id+'"><span>'+senpai('smile',v)+'</span><span><small>SENPAI KỂ</small><b>'+esc(x.kase?x.kase.t:teaser(x.corner))+'</b></span>'+mi('arrow_forward')+'</button>':''))+'</article>';}
function f2DetailAction(id){var u=H(id),slotted=S.slots.indexOf(id)>=0;if(!u)return m3Button('start',id,'Rèn thẻ này','add');if(!slotted)return m3Button('slotit',id,'Đưa lên tay','add');if(u.status==='pause')return m3Button('unslot',id,'Cất thẻ','inventory_2','tonal');if(ready(id))return m3Button('lvup',id,'Lên cấp','arrow_forward');if(u.master)return m3Button('tokeep',id,'Sang duy trì','arrow_forward');return m3Record(id,dk());}
drawCard=function(){if(!CARD||!HMAP[CARD.id])return;var id=CARD.id,x=HMAP[id],tab=CARD.tab==='journal'?'journal':'card';CARD.tab=tab;var h=habitHeader33(id,tab)+'<div class="f2-body" id="habit-body33" role="tabpanel" aria-labelledby="habit-tab-'+tab+'">';if(tab==='journal')h+=habitJournal33(id);else h+=(CARD.back?f2DetailBack(id):f2DetailFront(id))+(!x.custom?'<button class="f2-how-link" data-act="how" data-v="'+id+'">'+mi('menu_book')+'<span><b>Cách làm'+(PRAC[id]?' · Thực tập 30 giây':'')+'</b><small>'+(x.steps?'Thẻ ngắn, học từng phần':'Các cấp và câu tiếng Nhật')+'</small></span>'+mi('arrow_forward')+'</button>':'');h+='</div>'+(tab==='card'?'<footer class="sbar f2-footer f2-detail-footer"><button class="f2-text-button" data-act="f2FlipDetail" aria-pressed="'+!!CARD.back+'">'+mi('swap_horiz')+(CARD.back?'Việc nhỏ':'Ý nghĩa')+'</button>'+f2DetailAction(id)+'</footer>':'');f2Mount('detail',h);};

// Only the mobile rendering changes; source lesson content and desktop markup stay intact.
function mobileHowMemory(html){
 if(window.innerWidth>=768)return html;
 var template=document.createElement('template');template.innerHTML=html;
 template.content.querySelectorAll('.dd').forEach(function(grid){
  var headings=grid.querySelectorAll('.hd');if(headings.length!==2)return;
  var yes=document.createElement('section'),no=document.createElement('section');
  yes.className='mobile-do-block';no.className='mobile-avoid-block';
  yes.appendChild(headings[0]);no.appendChild(headings[1]);
  grid.querySelectorAll('.yes').forEach(function(p){yes.appendChild(p);});
  grid.querySelectorAll('.no').forEach(function(p){no.appendChild(p);});
  grid.replaceChildren(yes,no);grid.classList.add('mobile-do-dont');
 });
 template.content.querySelectorAll('details.oops').forEach(function(details){
  var section=document.createElement('section');section.className='oops mobile-oops';
  Array.from(details.children).forEach(function(child){if(child.tagName==='SUMMARY'){var heading=document.createElement('p');heading.className='hw__k';heading.textContent=child.textContent;section.appendChild(heading);}else section.appendChild(child);});
  details.replaceWith(section);
 });
 return template.innerHTML;
}
