recordFeedback=function(id,d,removed){f2BaseRecordFeedback(id,d,removed);if(SAVE_STATE32==='error')toast('Chưa lưu trên máy. Phần đang làm vẫn còn trong trang này.<span class="record-feedback-actions"><button data-act="retrySave32">Thử lưu lại</button><button data-act="backup">Xuất bản sao</button></span>',12000);};
