function f3Tabs(items,selected,action,prefix,panel,label){return '<div class="f3-tabs" role="tablist" aria-label="'+label+'">'+items.map(function(t){var on=t[0]===selected;return '<button id="'+prefix+t[0]+'" role="tab" aria-controls="'+panel+'" aria-selected="'+on+'" tabindex="'+(on?'0':'-1')+'" data-act="'+action+'" data-v="'+t[0]+'">'+(t[2]?mi(t[2]):'')+'<span>'+t[1]+'</span></button>';}).join('')+'</div>';}
