var p4Open=openOv,p4Close=closeOv,p4Return=null;
function p4Describe(el){if(!el||el===document.body||el===document.documentElement)return null;var n=el.closest('[data-act],button,a[href],input,textarea,[tabindex]');if(!n)return null;return {node:n,id:n.id,act:n.getAttribute('data-act'),value:n.getAttribute('data-v'),firstClass:n.classList.length?n.classList[0]:''};}
openOv=function(html,mini){var current=document.activeElement,fromDialog=OV&&OV.contains(current),origin=fromDialog?p4Return:p4Describe(current)||p4Return;var o=p4Open(html,mini);p4Return=origin;return o;};
closeOv=function(silent){var existed=!!OV,origin=p4Return;p4Close(silent);if(!existed)return;setTimeout(function(){if(OV)return;var active=document.activeElement;if(active&&active!==document.body&&active!==document.documentElement&&active.isConnected)return;var target=origin&&origin.node&&origin.node.isConnected?origin.node:null;if(!target&&origin&&origin.id)target=document.getElementById(origin.id);if(!target&&origin&&origin.act){var items=Array.from(document.querySelectorAll('[data-act]')).filter(function(n){return n.getAttribute('data-act')===origin.act&&n.getAttribute('data-v')===origin.value&&n.getClientRects().length&&!n.disabled;});target=items.find(function(n){return origin.firstClass&&n.classList.contains(origin.firstClass);})||items[0];}if(!target)target=document.getElementById('pageTitle35');if(target&&target.getClientRects().length)target.focus({preventScroll:true});},0);};

